import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {groundAt,checkPosition,movePlayer} from './collision.js';
import {WalkUI} from './ui.js';
const $=s=>document.querySelector(s),view=$('#view');
let renderer,scene,camera,world,model,ready=false,started=false,paused=true,lightMode=true,sun;
const keys=new Set(),touchKeys=new Set(),eyeHeight=1.65,start={x:-2.3,z:6.4,yaw:.537,pitch:.025};
let player={x:start.x,z:start.z,y:0},yaw=start.yaw,pitch=start.pitch,drag=null,lastTime=0,lastUI=0,needsRender=true;
const stats={instances:0,drawCalls:0,triangles:0,frames:0};
const touch=matchMedia('(pointer:coarse)').matches||innerWidth<600;
const ui=new WalkUI({mode(state){needsRender=true;paused=state!=='playing';if(state==='playing')started=true;clearInput();lastTime=performance.now();},lock:lockPointer,reset,settings:applySettings},touch);
function fail(error){console.error('Walkthrough failed:',error);ui.error(error);window.__walkthroughError=String(error);}
function clearInput(){keys.clear();touchKeys.clear();drag=null;}
function syncCamera(){if(!camera)return;camera.position.set(player.x,player.y+eyeHeight,player.z);camera.rotation.set(pitch,yaw,0,'YXZ');}
function reset(){if(!world)return;needsRender=true;clearInput();player={x:start.x,z:start.z,y:groundAt(world.ground,start.x,start.z)??.18};yaw=start.yaw;pitch=start.pitch;syncCamera();}
function look(dx,dy){yaw-=dx*.0025*ui.settings.sensitivity;pitch=THREE.MathUtils.clamp(pitch-dy*.0025*ui.settings.sensitivity*(ui.settings.invert?-1:1),-1.25,1.25);syncCamera();}
async function lockPointer(){if(!ready||!ui.playing)return;if(!renderer.domElement.requestPointerLock){ui.notify('画面をドラッグして見回せます');return;}try{await renderer.domElement.requestPointerLock();}catch{ui.notify('画面をドラッグして見回せます');}ui.pointerChanged();}
function applySettings(s){if(!renderer)return;needsRender=true;const previousLight=lightMode;lightMode=s.quality==='light';renderer.shadowMap.enabled=!lightMode;renderer.setPixelRatio(Math.min(devicePixelRatio,lightMode?1.25:1.75));if(camera){camera.fov=s.fov;camera.updateProjectionMatrix();}if(model&&previousLight!==lightMode)model.traverse(o=>{if(o.isMesh)for(const m of Array.isArray(o.material)?o.material:[o.material])m.needsUpdate=true;});resize();}
function optimizeInstances(root){root.updateMatrixWorld(true);const groups=new Map();root.traverse(o=>{if(!o.isMesh||o.isInstancedMesh||o.isSkinnedMesh)return;const mats=Array.isArray(o.material)?o.material:[o.material];const key=o.geometry.uuid+':'+mats.map(m=>m.uuid).join(',');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);});for(const list of groups.values())if(list.length>=3){const source=list[0],inst=new THREE.InstancedMesh(source.geometry,source.material,list.length);inst.name='Shared '+source.name;list.forEach((o,i)=>inst.setMatrixAt(i,o.matrixWorld));inst.computeBoundingSphere();inst.castShadow=source.castShadow;inst.receiveShadow=source.receiveShadow;scene.add(inst);list.forEach(o=>o.removeFromParent());stats.instances+=list.length;}}
function tuneMeshes(root){root.traverse(o=>{if(o.isLight)o.visible=false;if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;if(o.isInstancedMesh)stats.instances+=o.count;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(m.map)m.map.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());if(/water|shallows|current/i.test(m.name)){m.transparent=true;m.opacity=Math.min(m.opacity,.78);m.depthWrite=false;m.roughness=.23;m.metalness=.12;}if(m.transparent&&m.alphaTest>0)m.depthWrite=true;}});}
function resize(){if(!renderer||!camera)return;needsRender=true;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}
function frame(now){requestAnimationFrame(frame);if(!ready)return;const dt=Math.min((now-lastTime)/1000,.15)||0;lastTime=now;
 if(ui.playing){let forward=(keys.has('KeyW')||keys.has('ArrowUp')||touchKeys.has('forward')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')||touchKeys.has('back')?1:0);let right=(keys.has('KeyD')||keys.has('ArrowRight')||touchKeys.has('right')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')||touchKeys.has('left')?1:0);const n=Math.hypot(forward,right);if(n){forward/=n;right/=n;const speed=(keys.has('ShiftLeft')||keys.has('ShiftRight'))?3.5:2.1;const dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*right)*speed*dt,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*right)*speed*dt;const res=movePlayer(world,player,dx,dz);player=res.position;if(res.blocked){const id=res.blocked;ui.notify(id==='water'?'田と水路には入れません':id==='boundary'?'この先は、今回の散策範囲の外です':id==='step'?'この段差は登れません':/house|porch|farmhouse/i.test(id)?'建物と縁側は、外からご覧ください':'井戸の脇を回ってみましょう',700);}}}
 syncCamera();if(ui.playing||needsRender){renderer.render(scene,camera);stats.frames++;needsRender=false;}ui.tick(now);
 if(now-lastUI>700){lastUI=now;stats.drawCalls=renderer.info.render.calls;stats.triangles=renderer.info.render.triangles;$('#location-label').textContent=player.x>-3.4?'水路沿いの道':player.z>1&&player.x>-8.6&&player.x<-4?'井戸のある庭':'農家の庭';}
}
async function init(){renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.type=THREE.PCFSoftShadowMap;view.append(renderer.domElement);scene=new THREE.Scene();scene.background=new THREE.Color('#b6c3c2');scene.fog=new THREE.Fog('#b6c3c2',32,75);camera=new THREE.PerspectiveCamera(65,innerWidth/innerHeight,.06,100);scene.add(new THREE.HemisphereLight('#d6e4ec','#6d6045',2.3));sun=new THREE.DirectionalLight('#fff0cc',2.6);sun.position.set(-8,15,7);sun.target.position.set(-5,0,-2);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-18,right:18,top:18,bottom:-18,near:.1,far:55});sun.shadow.normalBias=.025;sun.shadow.bias=-.0002;scene.add(sun,sun.target);applySettings(ui.settings);
 const [gltf,data]=await Promise.all([new GLTFLoader().loadAsync('./assets/scene.glb',e=>ui.progress(e)),fetch('./assets/collision.json').then(r=>{if(!r.ok)throw Error('Ground data unavailable');return r.json();})]);world=data;model=gltf.scene;tuneMeshes(model);scene.add(model);optimizeInstances(model);ready=true;reset();ui.preparing();await renderer.compileAsync(scene,camera);renderer.render(scene,camera);ui.ready();requestAnimationFrame(frame);
 if(new URLSearchParams(location.search).has('qa'))setupQA();}
function setupQA(){window.__walktest={get state(){return{ready,started,paused,uiState:ui.state,settings:{...ui.settings},player:{...player},yaw,pitch,locked:!!document.pointerLockElement,stats:{...stats},bounds:world.bounds,boxes:world.boxes};},teleport(x,z,a=0){const q=checkPosition(world,x,z);if(!q.ok)throw Error('Invalid test position '+JSON.stringify(q));player={x,z,y:q.y};yaw=a;pitch=0;syncCamera();return this.state;},move(dx,dz){const res=movePlayer(world,player,dx,dz);player=res.position;syncCamera();return res;},reset};const panel=document.createElement('div');panel.id='qa-controls';const output=document.createElement('span');output.id='qa-output';const report=text=>output.textContent=`${text} | x=${player.x.toFixed(3)} z=${player.z.toFixed(3)} height=${player.y.toFixed(3)}`;for(const [label,x,z,a] of [['家の前',-9,0,0],['井戸の西',-8.5,2,-Math.PI/2],['水際',-2.3,5,-Math.PI/2],['外周',-14,5,Math.PI/2]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{window.__walktest.teleport(x,z,a);ui.play(false);report(label);};panel.append(b);}const b=document.createElement('button');b.textContent='前へ2m';b.onclick=()=>{const r=window.__walktest.move(-Math.sin(yaw)*2,-Math.cos(yaw)*2);report('result: '+(r.blocked||'clear'));};panel.append(b,output);$('#qa-mount').append(panel);report('Ready');}
window.addEventListener('keydown',e=>{if(e.code==='Escape'){if(ui.playing&&!document.pointerLockElement){e.preventDefault();ui.open();}return;}if(!ui.playing||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'].includes(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='KeyR'&&!e.repeat){reset();ui.notify('出発点に戻りました');}if(e.code==='KeyH'&&!e.repeat){e.preventDefault();ui.toggleHUD();}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();ui.pause();});document.addEventListener('visibilitychange',()=>{clearInput();lastTime=performance.now();if(document.hidden)ui.pause();});document.addEventListener('pointerlockchange',()=>{clearInput();if(!document.pointerLockElement&&ui.playing)ui.pause();ui.pointerChanged();});document.addEventListener('mousemove',e=>{if(ui.playing&&document.pointerLockElement===renderer?.domElement)look(e.movementX,e.movementY);});
view.addEventListener('pointerdown',e=>{if(!ui.playing||document.pointerLockElement)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);});view.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id||!ui.playing)return;look(e.clientX-drag.x,e.clientY-drag.y);drag.x=e.clientX;drag.y=e.clientY;});view.addEventListener('pointerup',()=>drag=null);view.addEventListener('pointercancel',()=>drag=null);for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{if(!ui.playing)return;e.preventDefault();touchKeys.add(b.dataset.move);b.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>touchKeys.delete(b.dataset.move));}window.addEventListener('resize',resize);window.addEventListener('error',e=>{if(!ready)fail(e.error||e.message);});window.addEventListener('unhandledrejection',e=>{if(!ready)fail(e.reason);});init().catch(fail);
